<?php $this->layout('layouts/studio'); $labels=['open'=>'Abertos','in_progress'=>'Em atendimento','waiting_customer'=>'Aguardando cliente','resolved'=>'Resolvidos','closed'=>'Fechados']; $priorityLabels=['low'=>'Baixa','medium'=>'Média','high'=>'Alta','urgent'=>'Urgente']; $slaLabels=['low'=>'120h','medium'=>'72h','high'=>'48h','urgent'=>'24h']; $whatsDigits=preg_replace('/\D+/', '', (string)($settings->site_whatsapp??'')); $whatsDigits=strlen($whatsDigits)>=10?$whatsDigits:''; ?>
<section class="organic-page-header"><div><p class="organic-eyebrow">Atendimento</p><h1 class="organic-page-title">Chamados</h1><p class="organic-page-description">Centralize solicitações, acompanhe prioridades e distribua o atendimento ao time.</p></div><button class="organic-btn organic-btn-primary" type="button" data-organic-modal-open="#ticket-create-modal"><ion-icon name="add-outline"></ion-icon>Abrir chamado</button></section>
<nav class="organic-tabs studio-ticket-tabs" aria-label="Status dos chamados"><a class="organic-tab <?= $status===''?'organic-tab-active':'' ?>" href="<?= url('/studio/tickets') ?>">Todos <small class="organic-tab-count"><?= array_sum($counts) ?></small></a><?php foreach($labels as $key=>$label):?><a class="organic-tab <?= $status===$key?'organic-tab-active':'' ?>" href="<?= url('/studio/tickets?status='.$key) ?>"><?= $label ?><small class="organic-tab-count"><?= $counts[$key] ?></small></a><?php endforeach;?></nav>
<section class="organic-card"><header class="organic-card-header studio-list-toolbar"><form class="organic-cluster" method="get" action="<?= url('/studio/tickets') ?>"><input class="organic-input" type="search" name="q" value="<?= htmlspecialchars($search) ?>" placeholder="Buscar protocolo, assunto ou solicitante"><button class="organic-btn" type="submit"><ion-icon name="search-outline"></ion-icon>Buscar</button></form><span class="organic-text-muted organic-text-sm"><?= count($tickets) ?> chamado(s)</span></header><div class="organic-table-wrapper"><table class="organic-table studio-ticket-table"><thead><tr><th>Chamado</th><th>Solicitante</th><th>Área</th><th>Prioridade / SLA</th><th>Status</th><th>Responsável</th><th>Prazo</th></tr></thead><tbody><?php if(!$tickets):?><tr><td class="organic-table-empty" colspan="7">Nenhum chamado encontrado.</td></tr><?php endif;?><?php foreach($tickets as $ticket): $completed=in_array($ticket->status,['resolved','closed'],true); $late=!$completed&&strtotime($ticket->due_at)<time(); ?><tr><td><a class="studio-ticket-link" href="<?= url('/studio/tickets?ticket='.$ticket->id) ?>"><strong><?= htmlspecialchars($ticket->subject) ?></strong><small>#<?= htmlspecialchars($ticket->protocol) ?></small></a></td><td><?= htmlspecialchars($ticket->requester_name?:'Não identificado') ?></td><td><?= ['general'=>'Geral','technical'=>'Técnico','financial'=>'Financeiro'][$ticket->area] ?></td><td><span class="organic-badge organic-badge-<?= in_array($ticket->priority,['high','urgent'],true)?'danger':($ticket->priority==='medium'?'warning':'success') ?>"><?= $priorityLabels[$ticket->priority] ?> · <?= $slaLabels[$ticket->priority] ?></span></td><td><span class="organic-badge <?= $completed?'organic-badge-success':($ticket->status==='waiting_customer'?'organic-badge-warning':'organic-badge-primary') ?>"><?= $labels[$ticket->status] ?></span></td><td><form class="studio-ticket-update" action="<?= url('/studio/tickets') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="update"><input type="hidden" name="ticket_id" value="<?= $ticket->id ?>"><select class="organic-select" name="assigned_to" onchange="this.form.requestSubmit()"><option value="">Não definido</option><?php foreach($users as $item):?><option value="<?= $item->id ?>" <?= $ticket->assigned_to==$item->id?'selected':'' ?>><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select><select class="organic-select" name="status" onchange="this.form.requestSubmit()"><?php foreach($labels as $key=>$label):?><option value="<?= $key ?>" <?= $ticket->status===$key?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></form></td><td><small class="<?= $late?'studio-sla-late':'' ?>"><?= $completed?'Finalizado':($late?'SLA vencido':'até '.date_fmt($ticket->due_at,'d/m H:i')) ?></small></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($selectedTicket): ?><section class="organic-card studio-ticket-detail"><header class="organic-card-header"><div><p class="organic-eyebrow">#<?= htmlspecialchars($selectedTicket->protocol) ?> · SLA <?= $slaLabels[$selectedTicket->priority] ?></p><h2 class="organic-card-title"><?= htmlspecialchars($selectedTicket->subject) ?></h2></div><a class="organic-btn organic-btn-icon" href="<?= url('/studio/tickets') ?>" aria-label="Fechar detalhes"><ion-icon name="close-outline"></ion-icon></a></header><div class="organic-card-body organic-stack"><p><?= nl2br(htmlspecialchars($selectedTicket->message)) ?></p><p class="organic-alert <?= strtotime($selectedTicket->due_at)<time()&&!in_array($selectedTicket->status,['resolved','closed'],true)?'organic-alert-danger':'' ?>">Prazo de atendimento: <strong><?= date_fmt($selectedTicket->due_at,'d/m/Y H:i') ?></strong>.</p><?php if($whatsDigits):?><a class="organic-btn organic-btn-outline" target="_blank" rel="noopener" href="https://wa.me/<?= $whatsDigits ?>?text=<?= urlencode('Olá! Sobre o chamado '.$selectedTicket->protocol.' — '.$selectedTicket->subject.'.') ?>"><ion-icon name="logo-whatsapp"></ion-icon>Abrir conversa no WhatsApp</a><?php endif; ?><div class="studio-ticket-history"><?php foreach($messages as $item):?><article><strong><?= htmlspecialchars($item->user_name) ?></strong><small><?= date_fmt($item->created_at,'d/m/Y H:i') ?><?= $item->is_internal?' · Nota interna':'' ?></small><p><?= nl2br(htmlspecialchars($item->message)) ?></p></article><?php endforeach;?></div><form class="organic-form" action="<?= url('/studio/tickets') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="reply"><input type="hidden" name="ticket_id" value="<?= $selectedTicket->id ?>"><label class="organic-form-group organic-label">Nova interação<textarea class="organic-textarea" name="message" rows="4" required placeholder="Registre uma resposta ou nota do atendimento"></textarea></label><label class="organic-check organic-text-sm"><input type="checkbox" name="is_internal" value="1" checked> Nota interna</label><button class="organic-btn organic-btn-primary">Registrar interação</button></form></div></section><?php endif; ?>
<div class="organic-modal" id="ticket-create-modal" data-organic-modal aria-hidden="true"><div class="organic-modal-dialog"><header class="organic-modal-header"><h2 class="organic-modal-title">Abrir chamado</h2><button class="organic-modal-close" type="button" data-organic-modal-close aria-label="Fechar">×</button></header><form class="organic-form organic-modal-body" action="<?= url('/studio/tickets') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="create"><label class="organic-form-group organic-label">Assunto<input class="organic-input" name="subject" required placeholder="Descreva em poucas palavras"></label><label class="organic-form-group organic-label">Mensagem<textarea class="organic-textarea" name="message" rows="5" required placeholder="Informe os detalhes do atendimento"></textarea></label><div class="organic-grid organic-grid-2"><label class="organic-form-group organic-label">Área<select class="organic-select" name="area"><option value="general">Geral</option><option value="technical">Técnico</option><option value="financial">Financeiro</option></select></label><label class="organic-form-group organic-label">Prioridade<select class="organic-select" name="priority"><option value="low">Baixa</option><option value="medium" selected>Média</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label></div><label class="organic-form-group organic-label">Responsável<select class="organic-select" name="assigned_to"><option value="">Definir depois</option><?php foreach($users as $item):?><option value="<?= $item->id ?>"><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select></label><footer class="organic-modal-footer"><button class="organic-btn" type="button" data-organic-modal-close>Cancelar</button><button class="organic-btn organic-btn-primary">Criar chamado</button></footer></form></div></div>
